{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.ArrayInputSchema",
  "description": "Schema for an array input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the array.",
      "type": [
        "string",
        "null"
      ]
    },
    "minItems": {
      "description": "Minimum number of items required.",
      "type": [
        "integer",
        "null"
      ],
      "format": "uint64",
      "minimum": 0
    },
    "maxItems": {
      "description": "Maximum number of items allowed.",
      "type": [
        "integer",
        "null"
      ],
      "format": "uint64",
      "minimum": 0
    },
    "items": {
      "description": "Schema for each item in the array.",
      "$ref": "functions.expression.InputSchema"
    }
  },
  "required": [
    "items"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.AnyOfInputSchema",
  "description": "Schema for a union of possible types - input must match at least one.",
  "type": "object",
  "properties": {
    "anyOf": {
      "description": "The possible schemas that the input can match.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.InputSchema"
      }
    }
  },
  "required": [
    "anyOf"
  ]
}

